type Role = "admin" | "teacher" | "student";
type StudentForm = { fullName: string; email: string; documentId: string; birthDate: string; phone: string; guardianName: string; profilePhotoUrl: string; status: "active" | "inactive" };
type SubjectForm = { code: string; name: string; description: string; period: string; teacherId: string; color: string; active: boolean; studentIds: string[] };
type GradeForm = { studentId: string; subjectId: string; period: string; title: string; score: string; maxScore: string; notes: string };
type ActivityForm = { subjectId: string; title: string; description: string; dueAt: string; maxScore: string; status: "draft" | "published" | "closed"; file: File | null };

const blankStudent: StudentForm = { fullName: "", email: "", documentId: "", birthDate: "", phone: "", guardianName: "", profilePhotoUrl: "", status: "active" };
const blankSubject: SubjectForm = { code: "", name: "", description: "", period: "", teacherId: "", color: "#B69A5E", active: true, studentIds: [] };
const blankGrade: GradeForm = { studentId: "", subjectId: "", period: "", title: "", score: "", maxScore: "100", notes: "" };
const blankActivity: ActivityForm = { subjectId: "", title: "", description: "", dueAt: "", maxScore: "100", status: "draft", file: null };

function normaliseRole(role?: string): Role {
  return role === "admin" || role === "teacher" ? role : "student";
}

function roleLabel(role: Role) {
  return role === "admin" ? "Administrador" : role === "teacher" ? "Docente" : "Estudiante";
}

function messageFrom(error: unknown) {
  return error instanceof Error ? error.message : "No fue posible completar la operación.";
}

function dateForInput(value: Date | string | null | undefined) {
  if (!value) return "";
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? "" : date.toISOString().slice(0, 10);
}

function dateTimeForInput(value: Date | string | null | undefined) {
  if (!value) return "";
  const date = new Date(value);
  const offset = date.getTimezoneOffset() * 60_000;
  return new Date(date.getTime() - offset).toISOString().slice(0, 16);
}

function formatDate(value: Date | string | null | undefined) {
  if (!value) return "Sin fecha";
  return new Intl.DateTimeFormat("es-CO", { dateStyle: "medium" }).format(new Date(value));
}

function scoreLabel(score: number, maxScore: number) {
  return `${score}/${maxScore}`;
}

async function fileToPayload(file: File | null) {
  if (!file) return undefined;
  if (file.size > 6 * 1024 * 1024) throw new Error("El archivo debe pesar como máximo 6 MB.");
  const base64 = await new Promise<string>((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result).split(",")[1] || "");
    reader.onerror = () => reject(new Error("No se pudo procesar el archivo."));
    reader.readAsDataURL(file);
  });
  return { fileName: file.name, mimeType: file.type || "application/octet-stream", base64 };
}

