function toHex(value: number) { return Math.max(0, Math.min(255, Math.round(value))).toString(16).padStart(2, "0").toUpperCase(); }
async function analyzeInstitutionLogo(file: File) {
  if (file.size > 4 * 1024 * 1024) throw new Error("El logo debe pesar menos de 4 MB.");
  const base64 = await new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result || "").split(",")[1] || ""); reader.onerror = () => reject(new Error("No se pudo leer el logo.")); reader.readAsDataURL(file); });
  const image = await new Promise<HTMLImageElement>((resolve, reject) => { const element = new Image(); element.onload = () => resolve(element); element.onerror = () => reject(new Error("El archivo de logo no es válido.")); element.src = URL.createObjectURL(file); });
  const canvas = document.createElement("canvas"); canvas.width = 32; canvas.height = 32; const context = canvas.getContext("2d"); if (!context) throw new Error("No se pudo analizar el logo."); context.drawImage(image, 0, 0, 32, 32); URL.revokeObjectURL(image.src);
  const pixels = context.getImageData(0, 0, 32, 32).data; let r = 0; let g = 0; let b = 0; let count = 0;
  for (let index = 0; index < pixels.length; index += 4) { const alpha = pixels[index + 3]; const brightness = pixels[index] + pixels[index + 1] + pixels[index + 2]; if (alpha > 40 && brightness < 735) { r += pixels[index]; g += pixels[index + 1]; b += pixels[index + 2]; count += 1; } }
  const average = count ? [r / count, g / count, b / count] : [182, 154, 94];
  return { base64, primaryColor: `#${toHex(average[0])}${toHex(average[1])}${toHex(average[2])}`, secondaryColor: `#${toHex(average[0] * 0.28)}${toHex(average[1] * 0.28)}${toHex(average[2] * 0.28)}` };
}

